@js:(function(){
var Q = String.fromCharCode(34);
var B = String.fromCharCode(92);
var s = '' + result;
var out = [];
var comic = '';
var bu = '' + baseUrl;
var cmi = bu.indexOf('/comic/');
if (cmi >= 0) { comic = bu.substring(cmi + 7, cmi + 32); }
if (comic.length < 20) {
  var cmk = B + Q + 'comicId' + B + Q + ':' + B + Q;
  var p = s.indexOf(cmk);
  if (p >= 0) { var a0 = p + cmk.length; var b0 = s.indexOf(B + Q, a0); if (b0 > a0) { comic = s.substring(a0, b0); } }
}
var idmk = B + Q + 'id' + B + Q + ':' + B + Q;
var tmk = B + Q + 'title' + B + Q + ':' + B + Q;
var emk = B + Q + ',' + B + Q + 'number' + B + Q + ':';
var idx = 0;
while (true) {
  var e = s.indexOf(emk, idx);
  if (e < 0) { break; }
  idx = e + emk.length;
  var tOpen = s.lastIndexOf(tmk, e);
  if (tOpen < 0) { continue; }
  var ts = tOpen + tmk.length;
  if (ts >= e) { continue; }
  var iOpen = s.lastIndexOf(idmk, tOpen);
  if (iOpen < 0) { continue; }
  var is = iOpen + idmk.length;
  if (is >= tOpen) { continue; }
  var ic = s.indexOf(B + Q, is);
  if (ic < 0 || ic + 3 != tOpen) { continue; }
  var chap = s.substring(is, ic);
  if (chap.length < 20 || chap.charAt(0) != 'c' || chap.charAt(1) != 'm') { continue; }
  var title = s.substring(ts, e);
  out.push('<a href="https://shenqimanhua.net/read/' + comic + '/' + chap + '">' + title + '</a>');
}
return out;
})()
